const input = $input.first().json || {};

function generateEventId() {
  return `evt_${Date.now()}`;
}

function makeOutput({
  success,
  eventType = null,
  source = "webhook",
  origin = null,
  environment = "test",
  payload = {},
  error = null,
  nextAction = "route_to_failure_log"
}) {
  return {
    success,
    component_id: "C2-C",
    component_version: "v1",
    event_id: generateEventId(),
    event_type: eventType,
    source,
    received_at: new Date().toISOString(),
    payload,
    metadata: {
      origin,
      environment
    },
    error,
    next_action: nextAction
  };
}

if (!input || Object.keys(input).length === 0) {
  return [
    {
      json: makeOutput({
        success: false,
        error: {
          code: "EMPTY_INPUT",
          message: "Input object is empty.",
          field: "root"
        }
      })
    }
  ];
}

if (!input.data || typeof input.data !== "object") {
  return [
    {
      json: makeOutput({
        success: false,
        error: {
          code: "MISSING_DATA_OBJECT",
          message: "Input must include a data object.",
          field: "data"
        }
      })
    }
  ];
}

const data = input.data;
const config = input.config || {};

const eventType = data.event_type || null;
const source = data.source || "webhook";
const origin = data.origin || null;
const environment = data.environment || "test";
const payload = data.payload;
const requirePayload = config.require_payload !== false;
const defaultNextAction = config.default_next_action || "validate_payload";

if (!eventType) {
  return [
    {
      json: makeOutput({
        success: false,
        eventType: null,
        source,
        origin,
        environment,
        payload: payload || {},
        error: {
          code: "MISSING_EVENT_TYPE",
          message: "event_type is required.",
          field: "data.event_type"
        }
      })
    }
  ];
}

if (requirePayload && payload === undefined) {
  return [
    {
      json: makeOutput({
        success: false,
        eventType,
        source,
        origin,
        environment,
        payload: {},
        error: {
          code: "MISSING_PAYLOAD",
          message: "payload object is required.",
          field: "data.payload"
        }
      })
    }
  ];
}

if (requirePayload && (payload === null || typeof payload !== "object" || Array.isArray(payload))) {
  return [
    {
      json: makeOutput({
        success: false,
        eventType,
        source,
        origin,
        environment,
        payload: {},
        error: {
          code: "INVALID_PAYLOAD_TYPE",
          message: "payload must be a JSON object.",
          field: "data.payload"
        }
      })
    }
  ];
}

return [
  {
    json: makeOutput({
      success: true,
      eventType,
      source,
      origin,
      environment,
      payload: payload || {},
      error: null,
      nextAction: defaultNextAction
    })
  }
];
